// Pure rules of the flame duct figure. All numbers come from model.json.
// Node tests import this file; build.mjs inlines it into figure.js, so keep it free of imports.

const clamp = (value, low, high) => Math.min(high, Math.max(low, value));
const smoothstep = (t) => t * t * (3 - 2 * t);

function parseModel(raw) {
  const ids = new Set(Object.keys(raw.evidence));
  const cited = [
    ...raw.bench.o2_ids,
    ...raw.flow_points.flatMap((point) => point.ids),
    ...raw.weightless.fan_cut_ids,
    ...raw.weightless.standoff_ids,
    ...raw.weightless.quench_ids,
    ...raw.earth.standoff_ids,
    ...raw.earth.shape_ids,
    ...raw.earth.air_ids,
  ];
  const missing = cited.filter((id) => !ids.has(id));
  if (missing.length) throw new Error(`model.json cites evidence ids it does not hold: ${missing.join(", ")}`);
  const { burn_from_cm_s: from, full_at_cm_s: full } = raw.weightless;
  if (!(from < full)) throw new Error("model.json: burn_from_cm_s must be below full_at_cm_s");
  return raw;
}

function normalise(model, state) {
  const { min, max } = model.bench.flow_range_cm_s;
  const flow = Number.isFinite(state.flow_cm_s) ? clamp(state.flow_cm_s, min, max) : min;
  return { flow_cm_s: flow, fan: Boolean(state.fan), gravity: state.gravity === "1g" ? "1g" : "0g" };
}

function vigourAt(model, flow_cm_s) {
  const { burn_from_cm_s: from, full_at_cm_s: full } = model.weightless;
  return smoothstep(clamp((flow_cm_s - from) / (full - from), 0, 1));
}

/** What the model asks of the flame for a state: where it wants to be, before any dwell time. */
function regimeOf(model, state) {
  if (state.gravity === "1g") return { regime: "earth", vigour: 1 };
  if (!state.fan) return { regime: "cut", vigour: 0 };
  if (state.flow_cm_s < model.weightless.burn_from_cm_s) return { regime: "quench", vigour: 0 };
  return { regime: "burn", vigour: vigourAt(model, state.flow_cm_s) };
}

const o2Of = (model, gravity) => model.bench.o2_pct[gravity];

function airOf(state) {
  return state.fan ? state.flow_cm_s : 0;
}

const FLAME_WORDS = {
  lit: (gravity, vigour) => (gravity === "1g" ? "tall yellow teardrop, rising" : vigour < 0.34 ? "small pale-blue dome" : vigour < 0.8 ? "blue dome, leaning with the air" : "fuller blue dome, leaning with the air"),
  quench: () => "small blue dome, close to going out",
  dying: () => "going out",
  out: () => "out",
  lighting: () => "igniter glowing",
};

function flameWords(phase, gravity, vigour) {
  return FLAME_WORDS[phase](gravity, vigour);
}

/** Evidence ids behind what the figure shows for a state and flame phase. */
function evidenceIds(model, state, phase) {
  const ids = new Set(model.bench.o2_ids);
  if (state.gravity === "1g") {
    for (const id of [...model.earth.shape_ids, ...model.earth.air_ids, ...model.earth.standoff_ids]) ids.add(id);
    return [...ids];
  }
  for (const id of model.weightless.standoff_ids) ids.add(id);
  if (!state.fan || phase === "dying") for (const id of model.weightless.fan_cut_ids) ids.add(id);
  if (phase === "quench") for (const id of model.weightless.quench_ids) ids.add(id);
  const nearest = [...model.flow_points].reverse().find((point) => state.flow_cm_s >= point.flow_cm_s && state.fan);
  if (nearest && phase !== "out") for (const id of nearest.ids) ids.add(id);
  return [...ids];
}

// Pure shape functions for everything that moves or changes shape: fan blades, needles, pointer, levers and the flame.
// Each takes a projection `proj([x, y, z]) -> [sx, sy]` and a plain config object, so build.mjs draws the first frame
// with them and figure.js redraws every later frame with the very same source.

const TAU = Math.PI * 2;
const f1 = (n) => (Math.round(n * 10) / 10).toString();
const pathOf = (points, closed = true) => `M${points.map(([x, y]) => `${f1(x)} ${f1(y)}`).join("L")}${closed ? "Z" : ""}`;

function hull(points) {
  const sorted = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const half = (list) => {
    const out = [];
    for (const p of list) {
      while (out.length >= 2 && cross(out[out.length - 2], out[out.length - 1], p) <= 0) out.pop();
      out.push(p);
    }
    out.pop();
    return out;
  };
  return [...half(sorted), ...half([...sorted].reverse())];
}

function bladesPath(proj, b, angle) {
  const parts = [];
  for (let i = 0; i < b.count; i++) {
    const a = angle + (i / b.count) * TAU;
    const at = (r, da) => proj([b.x, r * Math.cos(a + da), b.z + r * Math.sin(a + da)]);
    const tip = b.outer - 2.4;
    parts.push(pathOf([at(b.hub - 1, -0.16), at(14, -0.3), at(24, -0.2), at(tip, -0.02), at(tip, 0.24), at(24, 0.42), at(14, 0.4), at(b.hub - 1, 0.22)]));
  }
  return parts.join("");
}

const dialAngle = (g, value) => ((-135 + (270 * (value - g.min)) / (g.max - g.min)) * Math.PI) / 180;

function needlePath(proj, g, value) {
  const a = dialAngle(g, value);
  const at = (r) => proj([g.x + r * Math.sin(a), g.y, g.z + r * Math.cos(a)]);
  return pathOf([at(g.tail), at(g.tip)], false);
}

const leverTip = (proj, lv, lean) => proj([lv.x + lean * lv.lean, lv.y, lv.z + lv.rise * (1 - 0.18 * Math.abs(lean))]);

function leverPath(proj, lv, lean) {
  return pathOf([proj([lv.x, lv.y, lv.z]), leverTip(proj, lv, lean)], false);
}

function pointerPath(proj, kn, share) {
  const a = kn.from + share * kn.span;
  const sx = Math.sin(a);
  const sy = -Math.cos(a);
  return pathOf([proj([kn.x + sx * kn.r0, kn.y + sy * kn.r0, kn.z]), proj([kn.x + sx * kn.r1, kn.y + sy * kn.r1, kn.z])], false);
}

const revolve = (proj, makers, steps) => {
  const points = [];
  for (const make of makers) for (let j = 0; j < steps; j++) points.push(proj(make((j / steps) * TAU)));
  return hull(points);
};

/**
 * Flame layers as screen paths. `f` holds the drawing numbers (cfg.flame) and the moment:
 * kind "dome" (weightless) or "teardrop" (Earth), size 0..1, wobble -1..1, sway -1..1.
 */
function flameShapes(proj, f) {
  return f.kind === "teardrop" ? teardrop(proj, f) : dome(proj, f);
}

function dome(proj, f) {
  const size = Math.max(0, Math.min(1, f.size));
  const R0 = (f.r_min + (f.r_max - f.r_min) * size) * (1 + 0.07 * f.wobble);
  const standoff = f.standoff_min + (f.standoff_max - f.standoff_min) * size;
  const tail = f.tail_min + (f.tail_max - f.tail_min) * size;
  const apex = f.x - standoff;
  const build = (scale, grow, stretch) => {
    const rows = [];
    const cap = R0 * scale;
    const length = cap + tail * stretch;
    const centre = (s, r) => (angle) => [apex + (standoff * (1 - scale) + s) * 1, r * Math.cos(angle), f.z + r * Math.sin(angle)];
    for (let i = 0; i <= 14; i++) {
      const s = (i / 14) * cap * grow;
      const u = (cap - s) / cap;
      rows.push(centre(s, cap * Math.sqrt(Math.max(0, 1 - u * u))));
    }
    for (let i = 1; i <= 12; i++) {
      const u = i / 12;
      rows.push(centre(cap + u * (length - cap), cap * Math.pow(1 - Math.pow(u, 2.1), 0.75)));
    }
    return revolve(proj, rows, 26);
  };
  const outer = build(1, 1, 1);
  const inner = build(0.66, 1, 0.78);
  const core = build(0.3, 1, 0.5);
  const glow = build(1.9, 1, 1.3);
  const base = proj([f.x, 0, f.z]);
  return { glow: pathOf(glow), shell: pathOf(outer), inner: pathOf(inner), core: pathOf(core), anchor: base };
}

function teardrop(proj, f) {
  const size = Math.max(0, Math.min(1, f.size));
  const R1 = f.tear_r * (0.7 + 0.3 * size);
  const H = f.tear_h * (0.55 + 0.45 * size) * (1 + 0.1 * f.wobble);
  const z0 = f.z + f.rod_r + f.tear_gap;
  const build = (scale, tall) => {
    const rows = [];
    for (let i = 0; i <= 24; i++) {
      const u = i / 24;
      const r = R1 * scale * 2.9 * Math.sqrt(u) * Math.pow(1 - u, 1.3);
      const sway = f.sway * 3.2 * u * u * scale;
      rows.push((angle) => [f.x + 2 + sway + r * Math.cos(angle), r * Math.sin(angle), z0 + u * H * tall]);
    }
    return revolve(proj, rows, 22);
  };
  return { glow: pathOf(build(1.8, 1.15)), shell: pathOf(build(1, 1)), inner: pathOf(build(0.62, 0.8)), core: pathOf(build(0.28, 0.4)), anchor: proj([f.x, 0, z0]) };
}

// Runtime of the flame duct figure. build.mjs puts MODEL, CONFIG and the pure functions of model.mjs and dynamic.mjs above this file.
const CALM = "(prefers-reduced-motion: reduce)";
const LIGHT_S = 1.1;
const FOLLOW = { air: 0.55, o2: 0.5, lever: 0.1, knob: 0.14, size: 0.45, rps: 0.9 };
const follow = (value, goal, dt, seconds) => goal + (value - goal) * Math.exp(-dt / seconds);
const lerp = (a, b, t) => a + (b - a) * t;

function projectionOf({ sinA, cosA, sinE, cosE, k, ox, oy }) {
  const forward = ([x, y, z]) => [ox + (x * sinA - y * cosA) * k, oy + ((x * cosA + y * sinA) * sinE - z * cosE) * k];
  const onPlane = (sx, sy, z) => {
    const u = (sx - ox) / k;
    const v = (sy - oy) / k + z * cosE;
    return [u * sinA + (v / sinE) * cosA, -u * cosA + (v / sinE) * sinA];
  };
  return { forward, onPlane };
}

export function mount(host) {
  const root = host.matches("[data-figure='flame-duct']") ? host : host.querySelector("[data-figure='flame-duct']");
  const svg = root.querySelector("svg");
  const part = (name) => svg.querySelector(`[data-part="${name}"]`);
  const control = (name) => svg.querySelector(`[data-control="${name}"]`);
  const cam = projectionOf(CONFIG.CAM);
  const still = matchMedia(CALM);
  const range = MODEL.bench.flow_range_cm_s;
  const dwell = MODEL.weightless.quench_dwell_s.value;
  const cutOut = MODEL.weightless.fan_cut_out_s;

  const el = {
    blades: part("blades"),
    air: part("needle-air"),
    o2: part("needle-o2"),
    pointer: part("pointer"),
    flame: part("flame"),
    layers: ["glow", "shell", "inner", "core", "rim"].map((name) => svg.querySelector(`.fd-f-${name}`)),
    igniter: part("igniter"),
    streams: part("streams"),
    leverFan: part("lever-fan"),
    leverGravity: part("lever-gravity"),
    tipFan: part("lever-fan-tip"),
    tipGravity: part("lever-gravity-tip"),
    lamps: Object.fromEntries([...svg.querySelectorAll("[data-lamp]")].map((lamp) => [lamp.dataset.lamp, lamp])),
    knob: control("knob"),
    fan: control("fan"),
    gravity: control("gravity"),
    out: Object.fromEntries([...root.querySelectorAll("[data-out]")].map((node) => [node.dataset.out, node])),
    live: root.querySelector("[data-live]"),
  };

  const { burn_from_cm_s: burnFrom, full_at_cm_s: fullAt } = MODEL.weightless;
  const tourFlow = { full: fullAt, mid: Math.round((burnFrom + fullAt) / 2), quench: burnFrom / 2 };
  let target = normalise(MODEL, { flow_cm_s: fullAt, fan: true, gravity: "0g" });
  const sim = {
    air: airOf(target),
    o2: o2Of(MODEL, target.gravity),
    spin: 0,
    rps: 0.5,
    lean: { fan: 1, gravity: -1 },
    knob: target.flow_cm_s / range.max,
    heat: 0,
    clock: 0,
    kind: "dome",
    mix: 1,
    flame: { phase: "lit", life: 1, size: vigourAt(MODEL, target.flow_cm_s), clock: 0, from: 1, quench: 0, fast: false },
  };
  const view = { text: {}, phase: "lit" };
  const tour = { on: !still.matches, step: -1, wait: CONFIG.TOUR.start_s };
  let frame = 0;
  let last = 0;
  let visible = false;
  let alive = true;
  let dragging = false;
  let liveTimer = 0;

  const emit = (source) => {
    const detail = { state: { ...target }, flame: sim.flame.phase, evidence: evidenceIds(MODEL, target, sim.flame.phase), source };
    root.dispatchEvent(new CustomEvent("figure:change", { bubbles: true, detail }));
  };

  const calmJump = () => {
    if (!still.matches) return;
    const reg = regimeOf(MODEL, target);
    const f = sim.flame;
    sim.air = airOf(target);
    sim.o2 = o2Of(MODEL, target.gravity);
    sim.lean = { fan: target.fan ? 1 : -1, gravity: target.gravity === "1g" ? 1 : -1 };
    sim.knob = target.flow_cm_s / range.max;
    sim.kind = target.gravity === "1g" ? "teardrop" : "dome";
    sim.mix = 1;
    f.size = reg.regime === "quench" ? 0.08 : reg.vigour;
    f.life = reg.regime === "cut" ? 0 : 1;
    f.phase = reg.regime === "cut" ? "out" : reg.regime === "quench" ? "quench" : "lit";
  };

  const setState = (next, source) => {
    const state = normalise(MODEL, { ...target, ...next });
    if (state.flow_cm_s === target.flow_cm_s && state.fan === target.fan && state.gravity === target.gravity) return;
    target = state;
    calmJump();
    describe();
    emit(source);
    wake();
  };

  const stopTour = () => {
    tour.on = false;
  };

  const flameStep = (dt) => {
    const f = sim.flame;
    const reg = regimeOf(MODEL, target);
    const good = reg.regime === "burn" || reg.regime === "earth";
    if (f.phase === "out") {
      if (good) {
        f.phase = "lighting";
        f.clock = 0;
      }
      return;
    }
    if (f.phase === "lighting") {
      f.clock += dt;
      f.life = clamp((f.clock - 0.55) / 0.7, 0, 1);
      f.size = reg.regime === "earth" ? 1 : reg.vigour;
      if (f.clock >= LIGHT_S) {
        f.phase = "lit";
        f.life = 1;
      }
      if (!good) f.phase = "dying";
      return;
    }
    if (f.phase === "dying") {
      f.clock += dt;
      f.life = 1 - smoothstep(clamp(f.clock / (f.fast ? 0.8 : cutOut), 0, 1));
      if (good && f.life > 0.5) {
        f.phase = "lit";
        f.life = 1;
      } else if (f.life <= 0.002) {
        f.life = 0;
        f.phase = "out";
      }
      return;
    }
    if (reg.regime === "cut") {
      f.phase = "dying";
      f.clock = 0;
      f.fast = false;
      return;
    }
    if (reg.regime === "quench") {
      if (f.phase !== "quench") {
        f.phase = "quench";
        f.clock = 0;
        f.from = f.size;
      }
      f.clock += dt;
      f.quench = clamp(f.clock / dwell, 0, 1);
      f.size = lerp(f.from, 0.08, smoothstep(f.quench));
      if (f.clock >= dwell) {
        f.phase = "dying";
        f.clock = 0;
        f.fast = true;
      }
      return;
    }
    f.phase = "lit";
    f.quench = 0;
    f.size = follow(f.size, reg.vigour, dt, FOLLOW.size);
  };

  const step = (dt) => {
    sim.clock += dt;
    const air = airOf(target);
    sim.air = follow(sim.air, air, dt, FOLLOW.air);
    sim.o2 = follow(sim.o2, o2Of(MODEL, target.gravity), dt, FOLLOW.o2);
    sim.lean.fan = follow(sim.lean.fan, target.fan ? 1 : -1, dt, FOLLOW.lever);
    sim.lean.gravity = follow(sim.lean.gravity, target.gravity === "1g" ? 1 : -1, dt, FOLLOW.lever);
    sim.knob = follow(sim.knob, target.flow_cm_s / range.max, dt, FOLLOW.knob);
    sim.rps = follow(sim.rps, target.fan ? 0.4 + 2.4 * (air / range.max) : 0, dt, FOLLOW.rps);
    sim.spin += sim.rps * dt * Math.PI * 2;
    const wanted = target.gravity === "1g" ? "teardrop" : "dome";
    if (sim.kind !== wanted) {
      sim.mix = Math.max(0, sim.mix - dt / 0.3);
      if (sim.mix === 0) sim.kind = wanted;
    } else sim.mix = Math.min(1, sim.mix + dt / 0.4);
    flameStep(dt);
    sim.heat = sim.flame.phase === "lighting" ? 1 : follow(sim.heat, 0, dt, 0.5);
  };

  const wobbleOf = () => {
    if (still.matches) return { wobble: 0, sway: 0 };
    const t = sim.clock * Math.PI * 2;
    const f = sim.flame;
    if (sim.kind === "teardrop") return { wobble: 0.55 * Math.sin(t * 3.1) + 0.3 * Math.sin(t * 5.3 + 0.7), sway: 0.7 * Math.sin(t * 2.1) + 0.3 * Math.sin(t * 3.7 + 1.1) };
    if (f.phase === "quench") return { wobble: (0.15 + 0.85 * f.quench) * Math.sin(t * 4.2), sway: 0 };
    return { wobble: 0.35 * Math.sin(t * 1.1) + 0.15 * Math.sin(t * 2.3 + 1), sway: 0 };
  };

  const write = (name, text) => {
    if (view.text[name] === text) return;
    view.text[name] = text;
    el.out[name].textContent = text;
  };

  const say = () => {
    const f = sim.flame;
    const air = Math.round(sim.air * 10) / 10;
    write("air", `${air >= 10 ? Math.round(sim.air) : air} cm/s`);
    write("fan", target.fan ? "on" : "off");
    write("gravity", target.gravity === "1g" ? "Earth" : "weightless");
    write("flame", flameWords(f.phase, target.gravity, f.size));
    if (view.phase === f.phase) return;
    view.phase = f.phase;
    emit("flame");
    clearTimeout(liveTimer);
    liveTimer = setTimeout(() => {
      if (alive) el.live.textContent = `Flame: ${flameWords(f.phase, target.gravity, f.size)}`;
    }, 300);
  };

  const draw = () => {
    const f = sim.flame;
    el.blades.setAttribute("d", bladesPath(cam.forward, CONFIG.DYN.blades, sim.spin));
    el.air.setAttribute("d", needlePath(cam.forward, CONFIG.DYN.gauges.air, clamp(sim.air, range.min, range.max)));
    el.o2.setAttribute("d", needlePath(cam.forward, CONFIG.DYN.gauges.o2, sim.o2));
    el.pointer.setAttribute("d", pointerPath(cam.forward, CONFIG.DYN.knob, sim.knob));
    el.leverFan.setAttribute("d", leverPath(cam.forward, CONFIG.DYN.levers.fan, sim.lean.fan));
    el.leverGravity.setAttribute("d", leverPath(cam.forward, CONFIG.DYN.levers.gravity, sim.lean.gravity));
    for (const [name, tip] of [["fan", el.tipFan], ["gravity", el.tipGravity]]) {
      const [tx, ty] = leverTip(cam.forward, CONFIG.DYN.levers[name], sim.lean[name]);
      tip.setAttribute("cx", tx.toFixed(1));
      tip.setAttribute("cy", ty.toFixed(1));
    }
    for (const [id, lamp] of Object.entries(el.lamps)) lamp.toggleAttribute("data-on", (id === "1g") === (target.gravity === "1g"));
    el.igniter.toggleAttribute("data-hot", sim.heat > 0.25);
    const strength = clamp(sim.air / 8, 0, 1);
    el.streams.style.opacity = (strength * 0.85).toFixed(2);
    el.streams.style.setProperty("--fd-flow-ms", `${Math.round(clamp(14000 / Math.max(sim.air, 1), 450, 9000))}ms`);
    const opacity = f.life * sim.mix;
    el.flame.setAttribute("opacity", opacity.toFixed(3));
    el.flame.dataset.kind = sim.kind;
    if (opacity > 0.004) {
      const shapes = flameShapes(cam.forward, { ...CONFIG.DYN.flame, kind: sim.kind, size: f.size, ...wobbleOf() });
      [shapes.glow, shapes.shell, shapes.inner, shapes.core, shapes.shell].forEach((d, i) => el.layers[i].setAttribute("d", d));
    }
    say();
  };

  const describe = () => {
    el.knob.setAttribute("aria-valuenow", String(Math.round(target.flow_cm_s * 10) / 10));
    el.knob.setAttribute("aria-valuetext", `${Math.round(target.flow_cm_s * 10) / 10} centimetres per second`);
    el.fan.setAttribute("aria-checked", String(target.fan));
    el.gravity.setAttribute("aria-checked", String(target.gravity === "1g"));
  };

  const tourStep = (dt) => {
    if (!tour.on) return;
    tour.wait -= dt;
    if (tour.wait > 0) return;
    tour.step = (tour.step + 1) % CONFIG.TOUR.steps.length;
    const { flow, fan, gravity, hold_s } = CONFIG.TOUR.steps[tour.step];
    tour.wait = hold_s;
    setState({ flow_cm_s: tourFlow[flow], fan, gravity }, "tour");
  };

  const tick = (now) => {
    const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
    last = now;
    tourStep(dt);
    step(dt);
    draw();
    describe();
    frame = visible && alive && !still.matches ? requestAnimationFrame(tick) : 0;
  };

  function wake() {
    if (frame || !alive) return;
    if (still.matches) {
      draw();
      describe();
      return;
    }
    if (visible) {
      last = 0;
      frame = requestAnimationFrame(tick);
    }
  }

  const observer = new IntersectionObserver(
    (entries) => {
      visible = entries[entries.length - 1].isIntersecting;
      if (visible) wake();
      else if (frame) {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    },
    { rootMargin: "120px 0px" },
  );
  observer.observe(svg);

  const flowFromPointer = (event) => {
    const box = svg.getBoundingClientRect();
    const sx = ((event.clientX - box.left) / box.width) * CONFIG.VIEW.width;
    const sy = ((event.clientY - box.top) / box.height) * CONFIG.VIEW.height;
    const kn = CONFIG.DYN.knob;
    const [x, y] = cam.onPlane(sx, sy, kn.z);
    const angle = Math.atan2(x - kn.x, -(y - kn.y));
    const share = angle >= kn.from && angle <= kn.from + kn.span ? (angle - kn.from) / kn.span : angle > 0 ? 1 : 0;
    return Math.round(share * range.max * 10) / 10;
  };

  const listeners = [];
  const on = (node, type, handler) => {
    node.addEventListener(type, handler);
    listeners.push(() => node.removeEventListener(type, handler));
  };

  on(el.knob, "pointerdown", (event) => {
    stopTour();
    dragging = true;
    el.knob.setPointerCapture(event.pointerId);
    setState({ flow_cm_s: flowFromPointer(event) }, "user");
  });
  on(el.knob, "pointermove", (event) => {
    if (dragging) setState({ flow_cm_s: flowFromPointer(event) }, "user");
  });
  const release = (event) => {
    dragging = false;
    if (el.knob.hasPointerCapture(event.pointerId)) el.knob.releasePointerCapture(event.pointerId);
  };
  on(el.knob, "pointerup", release);
  on(el.knob, "pointercancel", release);
  on(el.knob, "keydown", (event) => {
    const big = event.shiftKey ? 5 : 1;
    const moves = { ArrowRight: big, ArrowUp: big, ArrowLeft: -big, ArrowDown: -big, PageUp: 5, PageDown: -5 };
    let flow = null;
    if (event.key in moves) flow = target.flow_cm_s + moves[event.key];
    if (event.key === "Home") flow = range.min;
    if (event.key === "End") flow = range.max;
    if (flow === null) return;
    event.preventDefault();
    stopTour();
    setState({ flow_cm_s: flow }, "user");
  });
  const flip = (name) => () => {
    stopTour();
    setState(name === "fan" ? { fan: !target.fan } : { gravity: target.gravity === "1g" ? "0g" : "1g" }, "user");
  };
  for (const name of ["fan", "gravity"]) {
    on(el[name], "click", flip(name));
    on(el[name], "keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      flip(name)();
    });
  }
  on(still, "change", () => {
    calmJump();
    wake();
  });

  calmJump();
  draw();
  describe();
  emit("init");
  wake();

  return {
    set(state) {
      stopTour();
      setState(state, "api");
      wake();
    },
    destroy() {
      alive = false;
      cancelAnimationFrame(frame);
      clearTimeout(liveTimer);
      observer.disconnect();
      listeners.forEach((off) => off());
    },
  };
}
